// Isolated static preview. The only outbound operation is the ASSETS binding.
// Policy and compressed-asset mappings are generated by prepare_preview_host.py.

export function allowedHostname(hostname) {
  return hostname === 'pdd-drive.app' || hostname === 'localhost' ||
    hostname === '127.0.0.1' || hostname === '[::1]' ||
    /^pdd-domain-migration-preview\.[a-z0-9-]+\.workers\.dev$/.test(hostname);
}

export function decodedPath(pathname) {
  let path = pathname;
  for (let count = 0; count < 8; count++) {
    const next = decodeURIComponent(path);
    if (next === path) break;
    path = next;
  }
  if (!path.startsWith('/') || /[%\\\x00-\x1f\x7f]/.test(path) ||
      path.split('/').some(part => part === '.' || part === '..')) {
    throw new Error('Unsafe path');
  }
  return path;
}

function disabledPath(path) {
  return path.split('/').some(part => part.toLowerCase() === 'api' || part.toLowerCase().startsWith('__staging_disabled__'));
}

function acceptsGzip(value) {
  if (value === null || value.trim() === '') return true;
  const entries = new Map(value.toLowerCase().split(',').map(part => {
    const [name, ...parameters] = part.trim().split(';');
    const quality = parameters.find(item => item.trim().startsWith('q='));
    const q = quality === undefined ? 1 : Number(quality.trim().slice(2));
    return [name.trim(), Number.isFinite(q) && q > 0 && q <= 1];
  }));
  return entries.has('gzip') ? entries.get('gzip') : entries.get('*') === true;
}

export function createPreviewWorker(policyHeaders, compressedAssets = {}) {
  if (!policyHeaders || !policyHeaders['Content-Security-Policy'] ||
      !policyHeaders['X-Robots-Tag'] || policyHeaders['Cache-Control'] !== 'no-store') {
    throw new Error('Generated isolation policy is required');
  }
  const policy = Object.freeze({...policyHeaders});
  const compressed = new Map();
  for (const [path, value] of Object.entries(compressedAssets)) {
    if (decodedPath(path) !== path || disabledPath(path) ||
        value.assetPath !== path + '.gz' || !value.contentType ||
        !Number.isSafeInteger(value.gzipBytes) || value.gzipBytes <= 0) {
      throw new Error('Invalid compressed asset mapping');
    }
    compressed.set(path, Object.freeze({...value}));
  }
  const respond = (body, status, extraHeaders = {}) => new Response(body, {
    status, headers: {...policy, ...extraHeaders},
  });
  return {
    async fetch(request, env) {
      const url = new URL(request.url);
      if (!['https:', 'http:'].includes(url.protocol) || !allowedHostname(url.hostname)) {
        return respond(request.method === 'HEAD' ? null : 'Preview host is not allowed', 403);
      }
      if (!['GET', 'HEAD'].includes(request.method)) {
        return respond('Read-only preview', 405, {Allow: 'GET, HEAD'});
      }
      let path;
      try {
        path = decodedPath(url.pathname);
      } catch (_) {
        return respond(request.method === 'HEAD' ? null : 'Invalid path', 400);
      }
      if (disabledPath(path)) {
        return respond(request.method === 'HEAD' ? null : 'Disabled in isolated preview', 403);
      }
      // Encoded on-disk assets are an implementation detail, never an extra URL.
      if (path.endsWith('.gz')) return respond(null, 404);
      if (!env?.ASSETS || typeof env.ASSETS.fetch !== 'function') return respond(null, 503);
      if (path.endsWith('/')) path += 'index.html';
      const packed = compressed.get(path);
      if (packed && !acceptsGzip(request.headers.get('Accept-Encoding'))) {
        return respond(null, 406, {Vary: 'Accept-Encoding'});
      }
      const assetURL = new URL(url.origin);
      assetURL.pathname = packed ? packed.assetPath : path;
      let asset;
      try {
        // Never forward cookies, credentials, conditional headers or Range.
        // identity returns the actual stored .gz bytes, avoiding double coding.
        asset = await env.ASSETS.fetch(new Request(assetURL, {
          method: request.method, redirect: 'manual', headers: {'Accept-Encoding': 'identity'},
        }));
      } catch (_) {
        return respond(null, 502);
      }
      // Static hosting never redirects requests to a backend or login provider.
      if (asset.status >= 300 && asset.status < 400) return respond(null, 502);
      if (packed && asset.status !== 200) return respond(null, asset.status === 404 ? 404 : 502);
      const headers = new Headers(asset.headers);
      for (const [key, value] of Object.entries(policy)) headers.set(key, value);
      headers.delete('Set-Cookie');
      headers.delete('Location');
      headers.delete('Access-Control-Allow-Origin');
      if (packed) {
        if (headers.has('Content-Encoding') && headers.get('Content-Encoding') !== 'identity') {
          return respond(null, 502);
        }
        headers.set('Content-Encoding', 'gzip');
        headers.set('Content-Type', packed.contentType);
        headers.set('Content-Length', String(packed.gzipBytes));
        headers.set('Vary', 'Accept-Encoding');
        headers.delete('Accept-Ranges');
        headers.delete('Content-Range');
      }
      return new Response(request.method === 'HEAD' ? null : asset.body, {
        status: asset.status, statusText: asset.statusText, headers,
        ...(packed ? {encodeBody: 'manual'} : {}),
      });
    },
  };
}
